mapper.select:
SELECT r.id, r.borrow_no, r.user_id, r.book_id, r.book_title, r.book_isbn, r.status, r.borrowed_at, r.due_at, r.returned_at, r.renew_count, r.fine_amount, r.fine_status, r.created_at, r.updated_at, u.username, u.real_name FROM borrow_record r LEFT JOIN sys_user u ON u.id = r.user_id AND u.deleted = 0 WHERE r.deleted = 0
AND r.user_id = #{userId}
AND r.status = #{status}
AND ( r.borrow_no LIKE CONCAT('%', #{keyword}, '%') OR r.book_title LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR u.real_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY r.borrowed_at DESC, r.id DESC
